    function startFly(t: any) { sFlap(); P.state = "fly"; P.fly = { t: 0, land: false, tgt: t }; for (let i = 0; i < 2; i++) spawnFeather(0.5) }
    function startPeck(t: any) { P.state = "peck"; P.peck = { c: t.c, u: 0, n: 0, hit: false }; P.v = 0 }
