            if (a.state === "off" || b.state === "off" || a.z > 0.3 || b.z > 0.3) continue
            const dx = b.x - a.x, dy = b.y - a.y, d = Math.hypot(dx, dy) || 0.01, min = 0.72 * L * (a.sc + b.sc) / 2
            if (d >= min) continue
